CREATE TABLE products (
    id    INTEGER PRIMARY KEY,
    name  TEXT    NOT NULL,
    price REAL    NOT NULL
);
INSERT INTO products VALUES (1, 'Laptop',   999.99);
INSERT INTO products VALUES (2, 'Mouse',     29.99);
INSERT INTO products VALUES (3, 'Keyboard',  79.99);
SELECT name, price
FROM   products
WHERE  price > 50
ORDER  BY price DESC;
